#!/usr/bin/env python3
import argparse
import json
import sqlite3
import sys
from datetime import datetime
from hashlib import sha256

def parse_args():
    parser = argparse.ArgumentParser()
    parser.add_argument('--db', required=True, help='path to SQLite database file')
    parser.add_argument('--key', required=True, help='path to key file')
    parser.add_argument('--log', required=True, help='path to log file')
    parser.add_argument('--level', help='filter by event level')
    parser.add_argument('--since', help='filter by timestamp since ISO-8601 UTC instant')
    parser.add_argument('--contains', help='filter by message substring')
    return parser.parse_args()

def compute_tag(key_path, event_data):
    with open(key_path, 'rb') as f:
        key_bytes = f.read()
    data = json.dumps(event_data, sort_keys=True).encode('utf-8')
    combined = key_bytes + data
    return sha256(combined).hexdigest().lower()

def process_events(db_path, key_path, level, since, contains):
    conn = None
    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute("SELECT id, ts, level, message FROM events ORDER BY id ASC")

        rows = []
        for row in cursor.fetchall():
            id_, ts, level_, message_ = row
            if level and level_ != level:
                continue
            if since:
                try:
                    since_dt = datetime.fromisoformat(since.replace('Z', '+00:00'))
                    if datetime.fromisoformat(ts.replace('Z', '+00:00')) < since_dt:
                        continue
                except ValueError:
                    continue
            if contains and contains not in message_:
                continue
            rows.append((id_, ts, level_, message_))

        return rows
    except Exception as e:
        raise e
    finally:
        if conn:
            conn.close()

def main():
    args = parse_args()
    try:
        rows = process_events(args.db, args.key, args.level, args.since, args.contains)
        tag = None
        if rows:
            first_event = rows[0]
            tag = compute_tag(args.key, {
                'id': first_event[0],
                'ts': first_event[1],
                'level': first_event[2],
                'message': first_event[3]
            })

        with open(args.log, 'a') as log_file:
            log_entry = datetime.utcnow().isoformat() + ' rows=' + str(len(rows)) + ' status=ok'
            log_file.write(log_entry + '\n')

        for row in rows:
            event = {
                'id': row[0],
                'ts': row[1],
                'level': row[2],
                'message': row[3],
                'tag': tag
            }
            print(json.dumps(event))

    except Exception as e:
        error_msg = str(e).replace('\n', ' ')
        with open(args.log, 'a') as log_file:
            log_entry = datetime.utcnow().isoformat() + ' status=error msg=' + error_msg + '\n'
            log_file.write(log_entry)
        sys.exit(1)

if __name__ == '__main__':
    main()

import sqlite3
import json
import os
import sys
from datetime import datetime
import hashlib

def compute_tag(key_bytes, id_val, ts_val, level_val, message_val):
    combined = key_bytes + id_val.encode('utf-8') + ts_val.encode('utf-8') + level_val.encode('utf-8') + message_val.encode('utf-8')
    return hashlib.sha256(combined).hexdigest().lower()

def main():
    if len(sys.argv) < 3 or len(sys.argv) > 4:
        print("Usage: python export_events.py DB_PATH KEY_PATH LOG_PATH [LEVEL]", file=sys.stderr)
        sys.exit(1)

    db_path = sys.argv[1]
    key_path = sys.argv[2]
    log_path = sys.argv[3]
    level = sys.argv[4] if len(sys.argv) > 4 else None

    try:
        with open(key_path, 'rb') as key_file:
            key_bytes = key_file.read()
    except IOError as e:
        print(f"status=error msg={str(e).replace('\n', ' ')}", file=open(log_path, 'w'))
        sys.exit(1)

    try:
        conn = sqlite3.connect(db_path)
        cursor = conn.cursor()
        cursor.execute("SELECT id, ts, level, message FROM events")
        rows = cursor.fetchall()
    except sqlite3.Error as e:
        print(f"status=error msg={str(e).replace('\n', ' ')}", file=open(log_path, 'w'))
        sys.exit(1)

    filtered_rows = []
    if level is not None:
        for row in rows:
            if row[2] == level:
                filtered_rows.append(row)
    else:
        filtered_rows = rows

    count = len(filtered_rows)
    output_lines = []

    for row in filtered_rows:
        id_val, ts_val, level_val, message_val = row
        tag = compute_tag(key_bytes, id_val, ts_val, level_val, message_val)
        output_line = json.dumps({
            'id': id_val,
            'ts': ts_val,
            'level': level_val,
            'message': message_val,
            'tag': tag
        })
        output_lines.append(output_line)

    try:
        with open(log_path, 'a') as log_file:
            log_file.write(f"{datetime.utcnow().strftime('%Y-%m-%dT%H:%M:%SZ')} rows={count} status=ok\n")
    except IOError as e:
        print(f"status=error msg={str(e).replace('\n', ' ')}", file=open(log_path, 'w'))
        sys.exit(1)

    for line in output_lines:
        print(line)

    sys.exit(0)
